<script setup lang="ts">
import { ArrowUpRight, Check, LoaderCircle } from 'lucide-vue-next'
import { divisions } from '~/data/divisions'
const api = useApi(); const route = useRoute()
useSeoMeta({ title: 'Contact Vomtek | Houston engineering and manufacturing', description: 'Talk to Vomtek about control panels, electrical work, electronics, motor service, fabrication or pipeline inspection in Houston.' })
const form = reactive({ name: '', email: '', company: '', type: String(route.query.division || 'control-systems'), message: '' })
const sent = ref(false); const loading = ref(false); const error = ref('')
const options = divisions.map(d => ({ value: d.slug, label: d.shortName, hint: d.tagline }))
async function submit() {
  loading.value = true; error.value = ''
  try { await api.request('/leads', { method: 'POST', body: { ...form, source: 'corporate-contact' } }); sent.value = true }
  catch (e: any) { error.value = e?.data?.message || 'Could not send. Email support@vomtek.com.' }
  finally { loading.value = false }
}
</script>
<template>
  <div>
    <section class="border-b border-ink/10 bg-white py-14 md:py-24"><div class="wrap grid gap-10 lg:grid-cols-12">
      <div class="lg:col-span-6"><p class="label-mono text-vomtek">Contact Vomtek</p><h1 class="type-page-hero mt-4 max-w-[12ch]">Tell us what<br><span class="text-vomtek">you need built.</span></h1><p class="mt-5 max-w-md text-[16px] leading-relaxed text-ink/70">A real person will reply within one business day. Tell us what is failing, what you are replacing or what you need to build.</p>
        <div class="mt-10 space-y-5 border-t border-ink/10 pt-6"><div><p class="label-mono text-ink/60">Email</p><a href="mailto:support@vomtek.com" class="mt-1 block text-[17px] font-medium hover:text-vomtek">support@vomtek.com</a></div><div><p class="label-mono text-ink/60">Phone</p><a href="tel:+17133471466" class="mt-1 block text-[17px] font-medium hover:text-vomtek">713-347-1466</a></div><div><p class="label-mono text-ink/60">Office</p><p class="mt-1 text-[15px] leading-relaxed text-ink/75">2401 Fountain View Dr, Ste 312<br>Houston, Texas 77057</p></div><div><p class="label-mono text-ink/60">Hours</p><p class="mt-1 text-[15px] text-ink/75">Monday–Friday, 8:00–17:00 CT</p></div></div></div>
      <div class="lg:col-span-6"><div v-if="sent" class="flex min-h-96 flex-col items-center justify-center rounded-2xl border border-vomtek/30 bg-vomtek/5 p-8 text-center"><span class="flex size-12 items-center justify-center rounded-full bg-vomtek text-white"><Check :size="22" /></span><h2 class="mt-5 font-display text-[32px] font-semibold">Message received.</h2><p class="mt-2 max-w-sm text-[14px] leading-relaxed text-ink/70">Someone from the right division will reply within one business day. For urgent breakdowns, call 713-347-1466.</p><NuxtLink to="/" class="btn btn-outline mt-6">Back to Vomtek</NuxtLink></div>
        <form v-else class="rounded-2xl border border-ink/12 bg-bone p-6 md:p-8" @submit.prevent="submit"><p class="font-display text-[27px] font-semibold">Send us a message</p><div class="mt-6 grid gap-5 sm:grid-cols-2"><div><label class="field-label">Your name</label><input v-model="form.name" required class="field" placeholder="Your name"></div><div><label class="field-label">Email</label><input v-model="form.email" required type="email" class="field" placeholder="you@company.com"></div><div><label class="field-label">Company</label><input v-model="form.company" class="field" placeholder="Company"></div><div><label class="field-label">What do you need?</label><AppSelect v-model="form.type" :options="options" placeholder="Choose a division" aria-label="Division" /></div><div class="sm:col-span-2"><label class="field-label">Tell us about the job</label><textarea v-model="form.message" required rows="5" class="field resize-none" placeholder="What is the equipment, what is going wrong, and when do you need it?" /></div></div><button class="btn btn-brand mt-6 w-full" :disabled="loading"><LoaderCircle v-if="loading" :size="15" class="animate-spin" /> {{ loading ? 'Sending…' : 'Send message' }} <ArrowUpRight v-if="!loading" :size="14" /></button><p v-if="error" class="mt-3 text-[12px] text-signal-deep">{{ error }}</p><p class="mt-4 text-[11px] leading-relaxed text-ink/60">We use your details only to reply and quote. We do not sell contact data.</p></form></div>
    </div></section>
    <section class="section-y"><div class="wrap grid gap-4 md:grid-cols-3"><NuxtLink v-for="item in [{t:'Control panels',d:'New builds, replacements and panel upgrades.',to:'/divisions/control-systems'},{t:'Motor & field service',d:'Repair, rewind, testing and on-site help.',to:'/divisions/motor-service'},{t:'Pipeline inspection',d:'Operators, utilities and home drain checks.',to:'/pipeline'}]" :key="item.t" :to="item.to" class="group rounded-xl border border-ink/12 bg-bone p-5"><h3 class="font-display text-[22px] font-semibold">{{ item.t }}</h3><p class="mt-2 text-[13px] leading-relaxed text-ink/70">{{ item.d }}</p><span class="mt-4 inline-flex items-center gap-1 font-mono text-[9px] uppercase tracking-[.08em] text-vomtek">Open <ArrowUpRight :size="11" /></span></NuxtLink></div></section>
  </div>
</template>
